internal static partial class WideCorpus
{
    private static WideModule Rook() => new("Rook", "The route planner admits work into regional dispatch queues. Counts, limits and ranks are nonnegative. Limits and capacities can be zero. The authorized input range keeps arithmetic within signed 64-bit bounds.",
    [
        Fault("SelectCarrier", "long firstPrice, long secondPrice, long firstRoom, long secondRoom, long units, long preference",
            "Return the selected carrier number, 1 or 2, or 0 if neither can carry units. Among eligible offers choose the lower price, or the specified preference when prices tie. Preference is 1 or 2.",
            "var eligibleFirst = units <= firstRoom;\nvar eligibleSecond = units <= secondRoom;\nif (!eligibleFirst || !eligibleSecond) return eligibleFirst ? 1 : eligibleSecond ? 2 : 0;\nif (firstPrice == secondPrice && firstRoom == secondRoom) return preference;\nreturn firstPrice < secondPrice || firstPrice == secondPrice && firstRoom > secondRoom ? 1 : 2;",
            "var eligibleFirst = units <= firstRoom;\nvar eligibleSecond = units <= secondRoom;\nif (!eligibleFirst || !eligibleSecond) return eligibleFirst ? 1 : eligibleSecond ? 2 : 0;\nif (firstPrice == secondPrice) return preference;\nreturn firstPrice < secondPrice ? 1 : 2;",
            [5, 8, 9, 9, 3, 2], 1, [5, 5, 9, 6, 3, 2], 2),
        Fault("AvailableLanes", "long lanes, long live, long maintenance, long liveInMaintenance",
            "A lane is unavailable if it is in use, under maintenance, or both. Counts are sizes of sets in the same snapshot. Return idle usable lanes.",
            "var blocked = live + maintenance;\nreturn Math.Max(lanes - blocked - liveInMaintenance, 0);",
            "var blocked = live + maintenance - liveInMaintenance;\nreturn lanes - blocked;",
            [12, 4, 1, 0], 7, [12, 4, 3, 2], 7),
        Fault("OutstandingJobs", "long accepted, long started, long finished, long retryQueued",
            "Each accepted job stays outstanding until finished, including while running. RetryQueued describes a subset of previously started unfinished jobs. Return the count still outstanding.",
            "var waiting = accepted - started + retryQueued;\nvar active = started - finished;\nreturn waiting + active;",
            "var waiting = accepted - started;\nvar active = started - finished;\nreturn waiting + active;",
            [18, 14, 12, 0], 6, [18, 14, 12, 1], 6),
        Fault("EvacuationThreshold", "long available, long required, long thresholdPercent, long overrideEnabled",
            "Without override, return 1 only when availability is at least the indicated integer percentage of requirement. Required is positive. Override always returns 1.",
            "if (overrideEnabled == 1) return 1;\nreturn available >= required * thresholdPercent / 100 ? 1 : 0;",
            "if (overrideEnabled == 1) return 1;\nreturn available * 100 >= required * thresholdPercent ? 1 : 0;",
            [6, 10, 50, 0], 1, [2, 3, 75, 0], 0),
        Fault("DispatchChannels", "long requested, long groupAllowed, long nodeAllowed, long stationDenied",
            "Return the bitmask of requested channels allowing either group or node approval, with station denials overriding both approval sources. Nonnegative masks share the same bit positions.",
            "var approved = (groupAllowed & ~stationDenied) | nodeAllowed;\nreturn requested & approved;",
            "var approved = (groupAllowed | nodeAllowed) & ~stationDenied;\nreturn requested & approved;",
            [15, 3, 4, 1], 6, [15, 3, 4, 5], 2),
        Fault("AffordableStop", "long shipping, long transfer, long load, long budget, long expedited",
            "Determine whether the dispatch cost fits budget. When expedited is set, waive transfer but charge both shipping and load. Otherwise all three count.",
            "var total = shipping + transfer + load;\nif (expedited == 1) total -= Math.Min(transfer, shipping);\nreturn total <= budget ? 1 : 0;",
            "var total = shipping + load + (expedited == 1 ? 0 : transfer);\nreturn total <= budget ? 1 : 0;",
            [8, 3, 2, 12, 1], 1, [5, 10, 2, 8, 1], 1),
        Fault("ResumeOffset", "long next, long acknowledgedFrom, long acknowledgedUntil, long limit",
            "A complete acknowledgment covers a contiguous interval including both of its bounds. Advance from next only if it is in that interval, never past limit. Inputs guarantee next is at or below limit.",
            "var creditedThrough = Math.Max(next, acknowledgedUntil + 1);\nif (acknowledgedUntil < next || acknowledgedFrom >= limit) return next;\nreturn Math.Min(creditedThrough, limit);",
            "if (next < acknowledgedFrom || next > acknowledgedUntil) return next;\nreturn Math.Min(acknowledgedUntil + 1, limit);",
            [5, 4, 9, 20], 10, [5, 7, 9, 20], 5),
        Fault("TransferBatches", "long requested, long freeUnits, long pending, long batchUnits, long cappedBatches",
            "A full batch debits batchUnits and incomplete ones stay pending. FreeUnits is measured before pending reservations. How many new batches of requested units can be granted within the cap? Batch size is positive.",
            "var free = Math.Max(freeUnits - pending / batchUnits * batchUnits, 0);\nreturn Math.Min(cappedBatches, Math.Min(requested / batchUnits, free / batchUnits));",
            "var free = Math.Max(freeUnits - pending, 0);\nreturn Math.Min(cappedBatches, Math.Min(requested / batchUnits, free / batchUnits));",
            [60, 60, 20, 10, 9], 4, [60, 23, 5, 10, 9], 1),
        Fault("RoutePreference", "long directGrade, long firstLeg, long secondLeg, long penalty, long minimum",
            "A grade of zero means no available leg. A transfer grade is the lower positive leg grade minus penalty, with a floor at zero. Return 2 for a viable transfer strictly better than direct, 1 for a viable direct route, or 0 if neither meets a positive minimum.",
            "var via = firstLeg == 0 || secondLeg == 0 ? 0 : Math.Max(Math.Max(firstLeg, secondLeg) - penalty, 0);\nif (via >= minimum && via > directGrade) return 2;\nreturn directGrade >= minimum ? 1 : 0;",
            "var via = firstLeg == 0 || secondLeg == 0 ? 0 : Math.Max(Math.Min(firstLeg, secondLeg) - penalty, 0);\nif (via >= minimum && via > directGrade) return 2;\nreturn directGrade >= minimum ? 1 : 0;",
            [4, 8, 8, 2, 2], 2, [4, 9, 5, 2, 2], 1),
        Fault("RetiredLabel", "long oldLabel, long newLabel, long receivedLabel, long migration, long dualReads",
            "During migration, accept only the new label plus the old label when dualReads is enabled. With no migration use the old label alone. Labels are distinct.",
            "var preferred = migration == 1 ? newLabel : oldLabel;\nreturn receivedLabel == preferred || dualReads == 1 && (receivedLabel == oldLabel || receivedLabel == newLabel) ? 1 : 0;",
            "var preferred = migration == 1 ? newLabel : oldLabel;\nreturn receivedLabel == preferred || migration == 1 && dualReads == 1 && receivedLabel == oldLabel ? 1 : 0;",
            [13, 18, 13, 1, 1], 1, [13, 18, 18, 0, 1], 0),
        Valid("SpareCapacity", "long physical, long committed, long quarantined", "Dedicated quarantine and committed capacity both reduce available room. If their sum exceeds physical capacity, the remaining room is zero.",
            "return Math.Max(physical - committed - quarantined, 0);", [20, 14, 9], 0),
        Valid("ShorterLane", "long primary, long alternate, long alternateEnabled", "Return the lower of the available lengths, including the primary lane even when the alternate is disabled.",
            "return alternateEnabled == 1 ? Math.Min(primary, alternate) : primary;", [8, 5, 0], 8)
    ]);

    private static WideModule Lattice() => new("Lattice", "The catalog service exports dataset slices, sample points and compact binary metadata. All arguments are nonnegative except when a rule permits otherwise. All named strides are positive and integer intermediates fit signed 64-bit arithmetic.",
    [
        Fault("PackedBytes", "long records, long width, long header, long alignment",
            "The common header has no padding. Each fixed-width record is padded up to alignment independently, including the last record. Return the byte count of the complete payload.",
            "var bytes = records * width;\nvar padded = bytes + (alignment - bytes % alignment) % alignment;\nreturn header + padded;",
            "var padded = width + (alignment - width % alignment) % alignment;\nreturn header + records * padded;",
            [4, 8, 2, 4], 34, [3, 5, 2, 4], 26),
        Fault("RemappedField", "long field, long firstDropped, long secondDropped, long added",
            "Return the new index of an original field that was retained after removing two distinct original positions. Finally prepend added fields. The supplied field is different from both dropped positions.",
            "var post = field - (firstDropped < field ? 1 : 0);\npost -= secondDropped < post ? 1 : 0;\nreturn post + added;",
            "var post = field - (firstDropped < field ? 1 : 0) - (secondDropped < field ? 1 : 0);\nreturn post + added;",
            [6, 1, 3, 2], 6, [6, 1, 5, 2], 6),
        Fault("SampleIndex", "long first, long last, long count, long percent",
            "The inclusive interval first to last contains count uniformly spaced sample positions, including both endpoints. Return the position of the truncated percent rank among indexes 0 through count minus one. Percent is 0 through 100, count is greater than one, and spacing is integral.",
            "var step = (last - first) / (count - 1);\nvar index = Math.Min(count - 1, count * percent / 100);\nreturn first + step * index;",
            "var step = (last - first) / (count - 1);\nvar index = (count - 1) * percent / 100;\nreturn first + step * index;",
            [10, 30, 5, 0], 10, [10, 30, 5, 40], 15),
        Fault("CatalogSelection", "long locator, long declared, long alias, long aliasApproved, long rejection",
            "An explicit rejection suppresses a locator. Otherwise an exact declared match is valid. A matching alias is valid only when approved. Return 1 for valid.",
            "if (locator == declared) return 1;\nreturn rejection == 0 && aliasApproved == 1 && locator == alias ? 1 : 0;",
            "if (rejection == 1) return 0;\nreturn locator == declared || aliasApproved == 1 && locator == alias ? 1 : 0;",
            [5, 7, 5, 1, 0], 1, [7, 7, 5, 1, 1], 0),
        Fault("CosignedCode", "long existing, long contribution, long occupiedMask, long availableMask",
            "Copy contribution bits only into available, unoccupied positions. Always preserve all existing bits, including occupied bits outside the available mask.",
            "var eligible = availableMask & ~occupiedMask;\nreturn existing & occupiedMask | contribution & eligible;",
            "var eligible = availableMask & ~occupiedMask;\nreturn existing | contribution & eligible;",
            [8, 7, 8, 15], 15, [10, 1, 8, 5], 11),
        Fault("SlopeDirection", "long a, long b, long c, long d, long startB, long startD",
            "Compare rise-to-run ratios from baseline startB to b over run a and from startD to d over run c. The runs a and c are positive, rises may be negative. Return -1, 0 or 1 for the first slope relative to the second.",
            "var ab = (b - startB) / a;\nvar cd = (d - startD) / c;\nreturn ab.CompareTo(cd);",
            "var ab = (b - startB) * c;\nvar cd = (d - startD) * a;\nreturn ab.CompareTo(cd);",
            [2, 10, 3, 8, 4, 2], 1, [3, 7, 2, 7, 5, 6], 1),
        Fault("GapRun", "long first, long middle, long last, long limit",
            "The points are sorted by position. Determine how many adjacent intervals meet the maximum gap rule. An interval of length exactly limit is valid.",
            "var firstGap = middle - first;\nvar lastGap = last - middle;\nvar mean = (firstGap + lastGap) / 2;\nif (mean > limit) return 0;\nreturn (firstGap <= limit ? 1 : 0) + (lastGap <= limit ? 1 : 0);",
            "var firstGap = middle - first;\nvar lastGap = last - middle;\nreturn (firstGap <= limit ? 1 : 0) + (lastGap <= limit ? 1 : 0);",
            [1, 4, 7, 3], 2, [1, 3, 13, 4], 1),
        Fault("ReplicaDigest", "long expected, long head, long witness, long headPresent, long witnessPresent",
            "If the current head is available it is authoritative, even if its digest is zero. An available witness may substitute only when the head is missing. Return 1 on a matching digest.",
            "if (headPresent == 1 && head != 0) return head == expected ? 1 : 0;\nreturn witnessPresent == 1 && witness == expected ? 1 : 0;",
            "if (headPresent == 1) return head == expected ? 1 : 0;\nreturn witnessPresent == 1 && witness == expected ? 1 : 0;",
            [22, 22, 19, 1, 0], 1, [42, 0, 42, 1, 1], 0),
        Fault("DenseRank", "long score, long first, long second, long third",
            "Rank score among the four values by dense descending rank. Larger distinct values occupy a single rank each, and tied values have the same rank.",
            "var below = new[] { first, second, third }.Count(item => item > score);\nreturn 1 + below;",
            "var below = new[] { first, second, third }.Where(item => item > score).Distinct().Count();\nreturn 1 + below;",
            [3, 5, 6, 1], 3, [3, 5, 5, 1], 2),
        Fault("MergeHeader", "long field, long origin, long overlay, long mask, long originPresent",
            "Merge fields from a mask. Mask bits select what can be overwritten by an overlay. A missing origin means an all-zero origin. Return 1 if the resulting field bit is set, with field a bit index from zero through 30.",
            "var basis = originPresent == 1 ? origin : 0;\nvar merged = basis | overlay & mask;\nreturn (merged & (1L << (int)field)) == 0 ? 0 : 1;",
            "var basis = originPresent == 1 ? origin : 0;\nvar merged = (basis & ~mask) | (overlay & mask);\nreturn (merged & (1L << (int)field)) == 0 ? 0 : 1;",
            [3, 2, 8, 8, 1], 1, [3, 8, 0, 8, 1], 0),
        Valid("RangeFloor", "long value, long floor, long ceiling", "Clamp a signed value to the ordered endpoints, returning either endpoint for an outlying value.",
            "return Math.Clamp(value, floor, ceiling);", [-4, -3, 9], -3),
        Valid("IdentityWord", "long low, long high", "Pack two 16-bit unsigned words into a 32-bit numeric value. Do not sign-extend the result.",
            "return (high << 16) | low;", [0xffff, 0xffff], 4294967295L)
    ]);
